module ddr4_0_lpf
   (lpf_int,
    slowest_sync_clk,
    ext_reset_in);
  output lpf_int;
  input slowest_sync_clk;
  input ext_reset_in;

  wire \ACTIVE_HIGH_EXT.ACT_HI_EXT_n_0 ;
  wire Q;
  wire [0:0]exr_lpf;
  wire ext_reset_in;
  wire lpf_exr;
